/** Overlay verified image data (written by scripts/fetch-images.mjs) onto each record. */
type Credit = { file: string; credit: string; licence: string; page: string; ratio?: number }
export const artworks = base.map((w) => {
  const c = (credits as Record<string, Credit>)[w.id]
  const src = localImage(w.id)
  if (!c || !src) return w
  return { ...w, image: { ...w.image, src, commonsFile: c.file || undefined, credit: c.credit, licence: c.licence, ratio: c.ratio ?? w.image.ratio } }
})
